2946	// ---------------------------------------------------------------------------
2947	// 候选资源组合的最早可行时段查询（find-slot，只读）
2948	//
2949	// 给定营业地时间窗口、所需连续分钟数与有顺序的需求组（每组列出可任选其一的
2950	// 已登记资源），在窗口内寻找能同时满足全部需求的最早开始分钟：每组恰选一个
2951	// 候选，全部所选资源互不相同，并在整个时段保持同一组合（不中途更换资源、
2952	// 不拼接间断时间）。各资源空闲时间 = 开放区间合并重叠或相接后扣除有效停用
2953	// 并集与当前有效预约占用（取消的预约/停用与未兑现候补不阻挡），区间左闭
2954	// 右开、端点相接可行。同一最早开始有多个组合时，按组顺序的资源标识序列取
2955	// 字典序最小者。本命令只读一份完整快照：不取写入保护、不创建任何记录、
2956	// 不写数据文件或推进计数；方案不保留位置，后续创建预约仍检查最新状态。
2957	// ---------------------------------------------------------------------------
2958	
2959	interface RequirementGroup {
2960	  index: number; // 1 基，需求组顺序
2961	  candidates: string[]; // 已校验、按标识排序的候选资源（组内输入顺序不影响结果）
2962	}
2963	
2964	// 解析并校验需求组：至少一组（由调用方保证），每组非空；
2965	// 组内重复或未知资源拒绝；同一资源允许出现在不同组（求解时保证所选互不相同）
2966	function parseRequirementGroups(store: Store, rawGroups: string[]): RequirementGroup[] {
2967	  return rawGroups.map((raw, i) => {
2968	    const label = `第 ${i + 1} 需求组`;
2969	    const ids = raw.split(',').map((s) => s.trim());
2970	    if (ids.some((s) => s === '')) {
2971	      throw new BizError(
2972	        `${label}为空或含空项: “${raw}”，应为逗号分隔的已登记资源标识（如 R0001,R0002）`,
2973	      );
2974	    }
2975	    const seen = new Set<string>();
2976	    const dupes: string[] = [];
2977	    for (const id of ids) {
2978	      if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
2979	      seen.add(id);
2980	    }
2981	    if (dupes.length > 0) throw new BizError(`${label}内候选资源重复: ${dupes.join('、')}`);
2982	    const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
