1	// shiftbook 候选资源组合最早可行时段查询（find-slot）自动化回归测试
2	//
3	// 运行：npm test（等价于 node --test test/，本文件随全部测试一起执行）
4	// 说明：
5	// - 使用 Node.js 24 内置测试运行器（node:test），无外部依赖、不访问网络；
6	// - 全部经命令行入口（node app.ts --data <临时文件>）操作，不读取用户默认数据文件；
7	// - 每个场景使用独立临时数据目录，保存结果由新进程查询；
8	// - 覆盖：重叠候选组须回溯调整前组选择、候选不足导致整体无解（各组各自可行
9	//   但整体不可行）、最早时间优先与同一最早开始的组合字典序取舍、跨日窗口与
10	//   停用/预约边界（端点相接）、各类占用（普通/系列成员/导入/候补兑现预约占用，
11	//   未兑现候补与已取消不阻挡）、改期或取消后重新查询、用法与非法请求的退出码、
12	//   旧数据文件兼容；查询前后数据文件逐字节不变（只读快照，不写文件不推进计数）；
13	// - 任一断言失败即非零退出，输出中标注场景与步骤；结束后自动清理临时文件。
14	
15	import {test} from 'node:test';
16	import assert from 'node:assert/strict';
17	import {spawnSync} from 'node:child_process';
18	import {mkdtempSync, rmSync, writeFileSync, readFileSync} from 'node:fs';
19	import {tmpdir} from 'node:os';
20	import {join, dirname} from 'node:path';
21	import {fileURLToPath} from 'node:url';
22	
23	const APP = join(dirname(fileURLToPath(import.meta.url)), '..', 'app.ts');
24	const OPEN_ALL: Array<[string, string]> = [['2026-01-01T00:00', '2027-01-01T00:00']];
25	
26	// ---------------------------------------------------------------------------
27	// 基础设施
28	// ---------------------------------------------------------------------------
29	
30	interface CliResult {
31	  status: number;
32	  stdout: string;
33	  stderr: string;
34	}
35	
36	function runCli(dataFile: string, args: string[]): CliResult {
37	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
38	  if (r.error) throw r.error;
39	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
40	}
41	
42	function ok(df: string, args: string[], ctx: string): CliResult {
43	  const r = runCli(df, args);
44	  assert.equal(
45	    r.status,
46	    0,
47	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
48	  );
49	  return r;
50	}
51	
52	function bizFail(df: string, args: string[], ctx: string): CliResult {
53	  const r = runCli(df, args);
54	  assert.equal(
55	    r.status,
56	    1,
57	    `[${ctx}] 期望退出 1，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
58	  );
59	  return r;
60	}
61	
62	function usageFail(df: string, args: string[], ctx: string): CliResult {
63	  const r = runCli(df, args);
64	  assert.equal(
65	    r.status,
66	    2,
67	    `[${ctx}] 期望退出 2，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
68	  );
69	  return r;
70	}
71	
72	function tempDir(t: {after: (fn: () => void) => void}): string {
73	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-find-slot-test-'));
74	  t.after(() => rmSync(dir, {recursive: true, force: true}));
75	  return dir;
76	}
