78	function addResource(
79	  df: string,
80	  name: string,
81	  open: Array<[string, string]> = OPEN_ALL,
82	  type = 'venue',
83	): void {
84	  const args = ['add-resource', '--type', type, '--name', name];
85	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
