255	  // 时长 181：超过 [01:00,04:00) 段长，只能取 [06:00,12:00] 段（预约结束点相接）
256	  const r3 = findSlot(df, '2026-10-12T20:00/2026-10-13T12:00', '181', ['R0001'], '跨日 181 分钟');
257	  assertSlot(r3, '2026-10-13T06:00', '2026-10-13T09:01', ['R0001'], '跨日 181 分钟');
