function parseFlexPlanItems(store: Store, records, file): FlexPlanItem[] {
  const problems: string[] = [];
  const items: Array<FlexPlanItem | null> = records.map((rec, idx) => {
    const at = `第 ${idx + 1} 项`;
    let ok = true;
    let win = null;
    try {
      win = parseFlexWindow(rec.window as string, `${at}窗口`);
    } catch (err) {
      if (err instanceof BizError) { problems.push(err.message); ok = false; }
      else throw err;
    }
    const duration = rec.duration as number;  // shape-checked positive integer
    if (win && duration > win.endMin - win.startMin) {
      problems.push(`${at} 所需连续时长 ${duration} 分钟超过窗口长度 ${win.endMin - win.startMin} 分钟（窗口: ${win.start} → ${win.end}）`);
      ok = false;
    }
    // groups
    const rawGroups = rec.groups as string[][];
    const groups: RequirementGroup[] = [];
    rawGroups.forEach((ids, g) => {
      const glabel = `${at} 第 ${g + 1} 需求组`;
      const seen = new Set<string>();
      const dupes = [];
      for (const id of ids) { if (seen.has(id) && !dupes.includes(id)) dupes.push(id); seen.add(id); }
      if (dupes.length) { problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`); ok = false; }
      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
      if (unknown.length) { problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`); ok = false; }
      groups.push({index: g + 1, candidates: [...seen].sort()});
    });
    if (!ok || win === null) return null;
    return {index: idx + 1, windowRaw: ..., startRaw: win.start, endRaw: win.end, startMin: win.startMin, endMin: win.endMin, duration, groups};
  });
  if (problems.length > 0) throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map(p => `- ${p}`).join('\n')}`);
  return items as FlexPlanItem[];
}
